snippet_css:
:root{
  --bg: #FFFFFF;
  --fg: #000000;
  --muted: #444444;
  --surface: #F0F0F0;
  --border: #000000;
  --accent: #0000EE;
  --accent-fg: #FFFFFF;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: #C0C0C0;
  --media-bg: #C0C0C0;
  --cta-bg: #F0F0F0;
  --input-bg: #FFFFFF;
  --ok: #007700;
  --warn: #AA0000;
  --font-display: 'Space Mono','Courier New',monospace;
  --font-body: 'Space Mono','Courier New',monospace;
  --font-mono: 'Space Mono',ui-monospace,Menlo,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
// tailwind.config.js → theme.extend
{
  "colors": {
    "bg": "#FFFFFF",
    "fg": "#000000",
    "muted": "#444444",
    "surface": "#F0F0F0",
    "border": "#000000",
    "accent": "#0000EE",
    "accent-fg": "#FFFFFF",
    "ok": "#007700",
    "warn": "#AA0000",
    "focus-ring": "var(--accent)"
  },
  "borderRadius": {
    "DEFAULT": "0px",
    "lg": "0px"
  },
  "fontFamily": {
    "display": [
      "'Space Mono','Courier New',monospace"
    ],
    "body": [
      "'Space Mono','Courier New',monospace"
    ]
  }
}
